<script lang="ts">import type {PageProps} from './$types';import {rupiah} from '$lib/format';import Icon from '$lib/Icon.svelte';import CurrencyInput from '$lib/components/CurrencyInput.svelte';let {data,form}:PageProps=$props();let newUnit=$state('');</script>
<div class="heading"><div><p class="eyebrow">KATALOG & PERSEDIAAN</p><h1>Stok barang</h1><p class="muted">Kelola harga, jumlah barang, dan pergerakan stok.</p></div></div>
{#if form?.success}<div class="notice">{form.success}</div>{/if}{#if form?.error}<div class="notice error">{form.error}</div>{/if}{#if data.error}<div class="notice error">{data.error}</div>{/if}
<details class="panel form-card"><summary class="summary"><Icon name="plus" size={14} /> Tambah barang baru</summary><form method="POST" action="?/create" class="form-grid" style="margin-top:18px"><label>Nama barang<input name="name" required maxlength="120" placeholder="Contoh: Beras pandan wangi" /></label><label>Satuan<select name="unit" bind:value={newUnit} required><option value="" disabled>Pilih satuan</option><option value="pcs">pcs</option><option value="bungkus">bungkus</option><option value="kg">kg</option></select></label><label>Harga modal<CurrencyInput name="cost_price" min={0} required /></label><label>Harga jual<CurrencyInput name="selling_price" min={1} required /></label><label>Stok awal ({newUnit || 'satuan'})<input name="current_stock" type="number" min="0" step={newUnit==='kg'?'0.001':'1'} inputmode={newUnit==='kg'?'decimal':'numeric'} value="0" required /></label><label>Batas minimum stok ({newUnit || 'satuan'})<input name="min_stock" type="number" min="0" step={newUnit==='kg'?'0.001':'1'} inputmode={newUnit==='kg'?'decimal':'numeric'} value="0" required /></label><div class="span-all"><small class="field-hint">{newUnit==='kg'?'Satuan kg dapat menggunakan pecahan hingga 3 angka desimal.':newUnit?'Satuan '+newUnit+' menggunakan jumlah utuh.':'Pilih satuan agar aturan jumlah stok sesuai.'}</small><button class="primary">Simpan barang</button></div></form></details>
<div class="section-title"><h2>Daftar barang <span class="count">{data.products.length}</span></h2><form method="GET" class="search"><input name="q" value={data.q} placeholder="Cari nama barang…" /><button class="secondary"><Icon name="search" size={16} /> Cari</button></form></div>
{#if data.products.length}<div class="product-list">{#each data.products as p}<article class="panel product"><div class="product-head"><span class="product-mark">{p.name.slice(0,1).toUpperCase()}</span><div class="product-name"><b>{p.name}</b><small>{p.unit} · Modal {rupiah(p.cost_price)}</small></div><span class:orange={Number(p.current_stock)<=Number(p.min_stock)} class="badge">{!p.is_active?'Nonaktif':Number(p.current_stock)<=Number(p.min_stock)?'Menipis':'Aktif'}</span></div><div class="stock-value"><strong>{p.current_stock}</strong><span>{p.unit} tersisa</span><small>Harga jual {rupiah(p.selling_price)} · Min. {p.min_stock}</small></div><details><summary class="summary">Kelola barang</summary><form method="POST" action="?/update" class="form-grid compact"><input type="hidden" name="id" value={p.id}/><label>Nama<input name="name" value={p.name} required /></label><label>Satuan<input name="unit" value={p.unit} required /></label><label>Harga modal<CurrencyInput name="cost_price" value={Number(p.cost_price)} min={0} required /></label><label>Harga jual<CurrencyInput name="selling_price" value={Number(p.selling_price)} min={1} required /></label><label>Batas minimum ({p.unit})<input name="min_stock" type="number" min="0" step={p.unit==='pcs'||p.unit==='bungkus'?'1':'0.001'} inputmode={p.unit==='pcs'||p.unit==='bungkus'?'numeric':'decimal'} value={p.min_stock} required /></label><div class="span-all"><button class="secondary">Simpan perubahan</button></div></form><form method="POST" action="?/stock" class="form-grid compact"><input type="hidden" name="product_id" value={p.id}/><label>Pergerakan<select name="movement_type"><option value="in">Stok masuk</option><option value="adjustment">Penyesuaian</option></select></label><label>Jumlah perubahan<input name="quantity" type="number" step="0.001" inputmode="decimal" required placeholder="Gunakan minus untuk mengurangi" /></label><label>Harga modal terbaru (opsional)<CurrencyInput name="new_cost" min={0} /></label><label>Catatan / alasan<input name="note" placeholder="Mis. restok / koreksi fisik" /></label><div class="span-all"><button class="primary">Simpan pergerakan</button></div></form>{#if p.is_active}<form method="POST" action="?/deactivate"><input type="hidden" name="id" value={p.id}/><button class="danger">Nonaktifkan barang</button></form>{/if}</details></article>{/each}</div>{:else}<div class="panel empty-state"><span><Icon name="grid" size={24}/></span><b>Belum ada barang ditemukan</b><p>Tambahkan barang pertama atau ubah kata pencarian.</p></div>{/if}
<div class="section-title"><h2>Riwayat pergerakan stok</h2></div>{#if data.movements.length}<div class="movement-list">{#each data.movements as m}<article class="panel movement"><span class="movement-mark">{#if m.movement_type==='sale'}<Icon name="cash" size={15}/>{:else if m.quantity_change>0}<Icon name="plus" size={15}/>{:else}<Icon name="refresh" size={15}/>{/if}</span><div><b>{data.products.find((p:any)=>p.id===m.product_id)?.name??'Barang'}</b><small>{m.movement_type==='sale'?'Penjualan':m.movement_type==='in'?'Stok masuk':'Penyesuaian'} · {m.note??'Transaksi kasir'}</small></div><strong class:negative={m.quantity_change<0}>{m.quantity_change>0?'+':''}{m.quantity_change}</strong></article>{/each}</div>{:else}<div class="panel empty-state"><b>Belum ada pergerakan stok</b><p>Pergerakan akan tercatat saat stok berubah atau ada penjualan.</p></div>{/if}
