:not(.compact)>label>input,.form-card .form-grid:not(.compact)>label>select{height:48px;box-sizing:border-box}.empty-state{display:grid;justify-items:center;padding:45px;color:var(--muted);text-align:center}.empty-state>span{font-size:32px;color:var(--purple);margin-bottom:10px}.empty-state b{color:var(--ink)}.empty-state p{font-size:16px;margin:7px 0 0}.orange{background:#F7E5E5;color:#C41E3A}@media(max-width:700px){.product-list,.movement-list{grid-template-columns:1fr}.section-title{align-items:flex-start;flex-direction:column}.search{width:100%}}
</style>
